.dm-ivx-w{position:relative;width:100%;max-width:420px;margin:0 auto}
.dm-ivx-h{display:flex;flex-direction:column;font-size:14px;line-height:20px;margin:0 calc(-1 * var(--dm-s-4)) var(--dm-s-1);padding:0 var(--dm-s-4) var(--dm-s-4);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-ivx-h b{font-weight:500}
.dm-ivx-h .dm-muted{font-size:12px;line-height:18px}
.dm-ivx-f{display:flex;align-items:flex-start;align-content:center;flex-wrap:wrap;gap:var(--dm-s-1);min-height:var(--dm-field-h);padding:5px 5px 5px var(--dm-s-2);border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);transition:box-shadow var(--dm-t-fast)}
