/* the buttons sit under a hairline from edge to edge, 16px under it; Copy link's glyph on the content's left edge, its hover
   box reaching out round it, and Send on the right edge */
.dm-ivx-ft{display:flex;justify-content:space-between;align-items:center;gap:6px;margin:0 calc(-1 * var(--dm-s-4)) 0;padding:var(--dm-s-4) var(--dm-s-4) 0;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.dm-ivx-ft .dm-ivx-link{padding:0 var(--dm-s-2);margin-left:calc(-1 * var(--dm-s-2));overflow:hidden;white-space:nowrap}
/* copied: the link's glyph turns into the green tick, the words stay the text colour, and the button eases to its new width */
.dm-ivx-link.dm-copied{color:var(--dm-fg)!important}
@media (hover:hover) and (pointer:fine){.dm-ivx-link.dm-copied:hover{color:var(--dm-fg)!important}}
