@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .dm-ivx-ft .dm-ivx-link:hover,:root [data-style="clean"] .dm-ivx-ft .dm-ivx-link:hover,:root [data-style="clean"].dm-ivx-ft .dm-ivx-link:hover{background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .dm-ivx-ft .dm-ivx-link:active,:root [data-style="clean"] .dm-ivx-ft .dm-ivx-link:active,:root [data-style="clean"].dm-ivx-ft .dm-ivx-link:active{box-shadow:var(--dm-btn2-press)}
