:root[data-style="clean"] .dm-ivx-ch.dm-bad>svg,:root [data-style="clean"] .dm-ivx-ch.dm-bad>svg,:root [data-style="clean"].dm-ivx-ch.dm-bad>svg{color:var(--dm-bad-mark)}
